output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts are forbidden in single-file shelf aisles, especially aisles with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent may not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "cartForbiddenAisle": {
          "and": [
            "singleFile",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {
        "enterCartForbiddenAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "cartForbiddenAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterCartForbiddenAisleWithCart"
    }
  },
  {
    "id": "park_cart_at_wide_mouth_before_narrow_fetch",
    "text": "Before fetching an item from a single-file shelf aisle, the cart should be parked at a wide aisle mouth.",
    "abstraction": {
      "state_properties": {
        "wideAisleMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartFreeFetchArea": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "wideAisleMouth",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterFetchAreaOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "cartFreeFetchArea"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterFetchAreaOnFoot",
      "discharge": "parkCart"
    }
  },
  {
    "id": "no_walking_without_cart_except_fetch_zone",
    "text": "Customers should not walk away from their cart except while in the narrow item-fetch zone or its wide parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "narrowFetchZone": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        },
        "wideParkingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "allowedOnFootZone": {
          "or": [
            "narrowFetchZone",
            "wideParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedOnFootZone"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_on_foot_shelf_service",
    "text": "After taking an item from a shelf while on foot in a narrow aisle, the agent must return to and pick up the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "narrowShelfServiceCell": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {
        "onFootShelfService": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "narrowShelfServiceCell",
              "INTERACT"
            ]
          },
          "post": null
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfService",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "park_cart_only_in_wide_cross_aisles",
    "text": "If a cart is set down, it should be parked only in a wide cross-aisle rather than in a cramped shelf bay.",
    "abstraction": {
      "state_properties": {
        "wideCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_shelf_interaction_in_single_file",
    "text": "Shelf interactions in single-file aisles must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfCell": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "singleFileShelfCell"
        ]
      }
    }
  },
  {
    "id": "cart_required_in_open_shopping_area",
    "text": "In open cart-compatible shopping areas, the agent is expected to keep possession of the cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartIncompatibleAisle": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        },
        "openCartCompatibleArea": {
          "not": "cartIncompatibleAisle"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openCartCompatibleArea",
          {
            "not": "hasCart"
          },
          "MOVE"
        ]
      }
    }
  }
]
